    @{ name = "launcher-win32-setup-1.0.34.551.exe";                                  size = 82586728 }
)

if (-not (Test-Path $installDir)) {
    New-Item -ItemType Directory -Path $installDir | Out-Null
}

$toDownload = @()
foreach ($f in $files) {
    $dest = Join-Path $installDir $f.name
    if (Test-Path $dest) {
        $actual = (Get-Item $dest).Length
        if ($f.size -and $actual -eq $f.size) {
            Write-Host "SKIP (complete): $($f.name)" -ForegroundColor Green
            continue
