        Write-Host "QUEUED: $($f.name)" -ForegroundColor Cyan
    }
    $toDownload += $f
}

$jobs = @()
foreach ($f in $toDownload) {
    $url  = $baseUrl + $f.name
    $dest = Join-Path $installDir $f.name
    $jobs += Start-Job -ScriptBlock {
        param($url, $dest, $name)
        try {
            $wc = New-Object System.Net.WebClient
            $wc.DownloadFile($url, $dest)
            Write-Output "DONE: $name"
